import 'package:flutter_test/flutter_test.dart';

import '../tool/generate_sbom.dart';

const _lock = '''
# Generated by pub
packages:
  args:
    dependency: transitive
    description:
      name: args
      sha256: "abc123"
      url: "https://pub.dev"
    source: hosted
    version: "2.7.0"
  flutter:
    dependency: "direct main"
    description: flutter
    source: sdk
    version: "0.0.0"
sdks:
  dart: ">=3.13.0 <4.0.0"
  flutter: ">=3.35.0"
''';

void main() {
  test('đọc gói hosted và gói sdk, không lẫn phần sdks', () {
    final packages = parseLockPackages(_lock);

    expect(packages.map((package) => package.name), ['args', 'flutter']);
    expect(packages.first.version, '2.7.0');
    expect(packages.first.source, 'hosted');
    expect(packages.first.sha256, 'abc123');
    expect(packages.last.source, 'sdk');
    expect(packages.last.sha256, isNull);
  });

  test('nhận diện giấy phép phổ biến', () {
    expect(detectLicense('Apache License Version 2.0'), 'Apache-2.0');
    expect(detectLicense('Mozilla Public License Version 2.0'), 'MPL-2.0');
    expect(
      detectLicense('Permission is hereby granted, free of charge, to any'),
      'MIT',
    );
    expect(
      detectLicense(
        'Redistribution and use in source and binary forms. '
        'Neither the name of Google',
      ),
      'BSD-3-Clause',
    );
    expect(
      detectLicense('Redistribution and use in source and binary forms.'),
      'BSD-2-Clause',
    );
    expect(detectLicense('tự viết'), 'NOASSERTION');
  });

  test('SBOM đúng dạng SPDX 2.3 và có đủ quan hệ', () {
    final sbom = buildSbom(
      appVersion: '1.0.0',
      created: DateTime.utc(2026, 11, 1, 7, 30),
      packages: parseLockPackages(_lock),
      licenseOf: (_) => 'MIT',
    );

    expect(sbom['spdxVersion'], 'SPDX-2.3');
    expect((sbom['creationInfo']! as Map)['created'], '2026-11-01T07:30:00Z');
    final packages = (sbom['packages']! as List).cast<Map<String, Object?>>();
    expect(packages, hasLength(3));
    expect(packages[1]['SPDXID'], 'SPDXRef-Package-args');
    expect(packages[1]['licenseDeclared'], 'MIT');
    expect(packages[1]['checksums'], isNotNull);
    expect(packages[2].containsKey('checksums'), isFalse);
    expect(sbom['relationships'], hasLength(3));
  });
}
